import os
import base64
import maya.cmds as cmds
import maya.OpenMayaUI as omui

try:
    from PySide6 import QtWidgets, QtCore, QtGui
    from shiboken6 import wrapInstance
except ImportError:
    from PySide2 import QtWidgets, QtCore, QtGui
    from shiboken2 import wrapInstance

# ---------------------------------------------------------------------
# EMBEDDED ASSETS (Base64)
# ---------------------------------------------------------------------
LOGO_BASE64 = b""

def get_icon_path():
    icon_dir = cmds.internalVar(userBitmapsDir=True)
    icon_path = os.path.join(icon_dir, "ref_logo.png")
    
    if not os.path.exists(icon_path):
        with open(icon_path, "wb") as f:
            f.write(base64.b64decode(LOGO_BASE64))
    return icon_path

# ---------------------------------------------------------------------
# CORE LOGIC
# ---------------------------------------------------------------------
class ReferenceLogic(object):
    def __init__(self):
        self.view_keywords = {
            "front": ["front", "face"],
            "side": ["side", "left", "right"],
            "top": ["top", "up"]
        }
        self.group_name = "REF_IMAGES"
        self.layer_name = "REF_LAYER"
        self.default_alpha = 0.5

    def detect_view(self, filename):
        lower_name = filename.lower()
        for view, keywords in self.view_keywords.items():
            for kw in keywords:
                if kw in lower_name:
                    return view
        return "front"

    def create_image_plane(self, filepath):
        plane = cmds.imagePlane(fileName=filepath)
        return plane[0], plane[1]

    def apply_settings(self, transform, shape, view_type):
        if view_type == "side":
            cmds.setAttr(f"{transform}.rotateY", 90)
        elif view_type == "top":
            cmds.setAttr(f"{transform}.rotateX", -90)

        cmds.setAttr(f"{shape}.alphaGain", self.default_alpha)

        current_unit = cmds.currentUnit(query=True, linear=True)
        if current_unit == 'm':
            cmds.setAttr(f"{transform}.scaleX", 100)
            cmds.setAttr(f"{transform}.scaleY", 100)
            cmds.setAttr(f"{transform}.scaleZ", 100)

        transform_attrs = ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']
        for attr in transform_attrs:
            cmds.setAttr(f"{transform}.{attr}", lock=True)

    def organize_scene(self, transforms):
        if not transforms:
            return

        if not cmds.objExists(self.group_name):
            cmds.group(empty=True, name=self.group_name)
        
        for t in transforms:
            current_parent = cmds.listRelatives(t, parent=True)
            if not current_parent or current_parent[0] != self.group_name:
                cmds.parent(t, self.group_name)

        if not cmds.objExists(self.layer_name):
            cmds.createDisplayLayer(name=self.layer_name, empty=True)
            cmds.setAttr(f"{self.layer_name}.displayType", 2)

        cmds.editDisplayLayerMembers(self.layer_name, transforms, noRecurse=True)

    def process_files(self, filepaths):
        results = []
        created_transforms = []
        for fp in filepaths:
            filename = os.path.basename(fp)
            view_type = self.detect_view(filename)
            try:
                transform, shape = self.create_image_plane(fp)
                self.apply_settings(transform, shape, view_type)
                created_transforms.append(transform)
                results.append(f"SUCCESS: {filename} -> {view_type.upper()} View (Auto)")
            except Exception as e:
                results.append(f"FAILED: {filename} ({str(e)})")

        self.organize_scene(created_transforms)
        return results

    def process_explicit_files(self, filepaths, view_type):
        results = []
        created_transforms = []
        for fp in filepaths:
            filename = os.path.basename(fp)
            try:
                transform, shape = self.create_image_plane(fp)
                self.apply_settings(transform, shape, view_type)
                created_transforms.append(transform)
                results.append(f"SUCCESS: {filename} -> FORCED {view_type.upper()} View")
            except Exception as e:
                results.append(f"FAILED: {filename} ({str(e)})")

        self.organize_scene(created_transforms)
        return results

    def toggle_visibility(self):
        if cmds.objExists(self.group_name):
            current_vis = cmds.getAttr(f"{self.group_name}.visibility")
            cmds.setAttr(f"{self.group_name}.visibility", not current_vis)
            return "SUCCESS: Toggled visibility."
        return "WARNING: No reference group found."

    def delete_all(self):
        deleted = False
        if cmds.objExists(self.group_name):
            children = cmds.listRelatives(self.group_name, children=True, fullPath=True) or []
            for child in children:
                for attr in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz', 'sx', 'sy', 'sz']:
                    cmds.setAttr(f"{child}.{attr}", lock=False)
            cmds.delete(self.group_name)
            deleted = True
            
        if cmds.objExists(self.layer_name):
            cmds.delete(self.layer_name)
            
        return "SUCCESS: All references deleted." if deleted else "WARNING: No references to delete."


# ---------------------------------------------------------------------
# USER INTERFACE
# ---------------------------------------------------------------------
class DropZone(QtWidgets.QLabel):
    files_dropped = QtCore.Signal(list)

    def __init__(self):
        super(DropZone, self).__init__("Drag & Drop Images Here\n\n(Auto-detects view from filename)")
        self.setAlignment(QtCore.Qt.AlignCenter)
        self.setMinimumHeight(120)
        self.setAcceptDrops(True)
        self.setStyleSheet("""
            QLabel { border: 2px dashed #888; border-radius: 8px; background-color: #2b2b2b; color: #ccc; font-size: 13px; }
        """)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()

    def dropEvent(self, event):
        urls = event.mimeData().urls()
        filepaths = [u.toLocalFile() for u in urls if u.isLocalFile()]
        valid_extensions = ('.png', '.jpg', '.jpeg', '.tga', '.tif', '.tiff', '.bmp')
        valid_files = [f for f in filepaths if f.lower().endswith(valid_extensions)]
        if valid_files:
            self.files_dropped.emit(valid_files)

class ReferenceUI(QtWidgets.QDialog):
    def __init__(self, parent=None):
        super(ReferenceUI, self).__init__(parent)
        self.setWindowTitle("Reference Image Importer")
        self.setMinimumWidth(450)
        self.setWindowFlags(self.windowFlags() ^ QtCore.Qt.WindowContextHelpButtonHint)

        self.logic = ReferenceLogic()
        self.build_ui()

    def build_ui(self):
        layout = QtWidgets.QVBoxLayout(self)
        layout.setSpacing(10)
        layout.setContentsMargins(15, 15, 15, 15)

        self.logo_label = QtWidgets.QLabel()
        icon_path = get_icon_path()
        pixmap = QtGui.QPixmap(icon_path)
        self.logo_label.setPixmap(pixmap.scaled(250, 80, QtCore.Qt.KeepAspectRatio, QtCore.Qt.SmoothTransformation))
        self.logo_label.setAlignment(QtCore.Qt.AlignCenter)
        layout.addWidget(self.logo_label)

        self.drop_zone = DropZone()
        self.drop_zone.files_dropped.connect(self.process_incoming_files)
        layout.addWidget(self.drop_zone)

        manual_group = QtWidgets.QGroupBox("Force View Assignment")
        manual_layout = QtWidgets.QHBoxLayout()
        
        self.btn_force_front = QtWidgets.QPushButton("Add Front")
        self.btn_force_front.clicked.connect(lambda: self.browse_explicit("front"))
        self.btn_force_side = QtWidgets.QPushButton("Add Side")
        self.btn_force_side.clicked.connect(lambda: self.browse_explicit("side"))
        self.btn_force_top = QtWidgets.QPushButton("Add Top")
        self.btn_force_top.clicked.connect(lambda: self.browse_explicit("top"))
        
        manual_layout.addWidget(self.btn_force_front)
        manual_layout.addWidget(self.btn_force_side)
        manual_layout.addWidget(self.btn_force_top)
        manual_group.setLayout(manual_layout)
        layout.addWidget(manual_group)

        manage_group = QtWidgets.QGroupBox("Manage References")
        manage_layout = QtWidgets.QHBoxLayout()
        
        self.btn_toggle = QtWidgets.QPushButton("Toggle Visibility")
        self.btn_toggle.clicked.connect(self.toggle_refs)
        
        self.btn_delete = QtWidgets.QPushButton("Delete All")
        self.btn_delete.setStyleSheet("background-color: #662222;")
        self.btn_delete.clicked.connect(self.delete_refs)
        
        manage_layout.addWidget(self.btn_toggle)
        manage_layout.addWidget(self.btn_delete)
        manage_group.setLayout(manage_layout)
        layout.addWidget(manage_group)

        btn_layout = QtWidgets.QHBoxLayout()
        self.btn_browse = QtWidgets.QPushButton("Auto-Detect Browse...")
        self.btn_browse.clicked.connect(self.browse_files)
        self.btn_clear = QtWidgets.QPushButton("Clear Feedback")
        self.btn_clear.clicked.connect(self.clear_feedback)
        btn_layout.addWidget(self.btn_browse)
        btn_layout.addWidget(self.btn_clear)
        layout.addLayout(btn_layout)

        self.feedback_list = QtWidgets.QListWidget()
        self.feedback_list.setSelectionMode(QtWidgets.QAbstractItemView.NoSelection)
        self.feedback_list.setStyleSheet("background-color: #1e1e1e; color: #aaa; border: 1px solid #444;")
        layout.addWidget(self.feedback_list)

        # --- MODIFIED/ADDED SECTION: AUTHOR CREDIT IN UI ---
        # Appends the requested exact copyright string to the bottom of the tool layout.
        copyright_text = (
            "Copyright (c) 2026 Bruce\n"
            "All rights reserved.\n"
            "This script may not be copied, modified, redistributed, or sold\n"
            "without explicit permission from the author."
        )
        self.copyright_label = QtWidgets.QLabel(copyright_text)
        self.copyright_label.setAlignment(QtCore.Qt.AlignCenter)
        self.copyright_label.setStyleSheet("color: #666666; font-size: 10px; margin-top: 8px;")
        layout.addWidget(self.copyright_label)
        # --- END ADDED SECTION ---

    def browse_files(self):
        filepaths, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self, "Select Images (Auto-Detect View)", "", "Image Files (*.png *.jpg *.jpeg *.tga *.tif *.tiff *.bmp)"
        )
        if filepaths:
            self.process_incoming_files(filepaths)

    def browse_explicit(self, view_type):
        filepaths, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self, f"Select Images for {view_type.upper()} View", "", "Image Files (*.png *.jpg *.jpeg *.tga *.tif *.tiff *.bmp)"
        )
        if filepaths:
            results = self.logic.process_explicit_files(filepaths, view_type)
            for res in results:
                self.feedback_list.addItem(res)
            self.feedback_list.scrollToBottom()

    def process_incoming_files(self, filepaths):
        results = self.logic.process_files(filepaths)
        for res in results:
            self.feedback_list.addItem(res)
        self.feedback_list.scrollToBottom()

    def toggle_refs(self):
        res = self.logic.toggle_visibility()
        self.feedback_list.addItem(res)
        self.feedback_list.scrollToBottom()

    def delete_refs(self):
        res = self.logic.delete_all()
        self.feedback_list.addItem(res)
        self.feedback_list.scrollToBottom()

    def clear_feedback(self):
        self.feedback_list.clear()


# ---------------------------------------------------------------------
# MAYA INTEGRATION & EXECUTION
# ---------------------------------------------------------------------
def get_maya_main_window():
    ptr = omui.MQtUtil.mainWindow()
    if ptr:
        return wrapInstance(int(ptr), QtWidgets.QMainWindow)
    return None

def launch_tool():
    global ref_importer_window
    try:
        if ref_importer_window:
            ref_importer_window.close()
            ref_importer_window.deleteLater()
    except NameError:
        pass

    maya_window = get_maya_main_window()
    ref_importer_window = ReferenceUI(maya_window)
    ref_importer_window.show()


# ---------------------------------------------------------------------
# DRAG AND DROP INSTALLER
# ---------------------------------------------------------------------
def onMayaDroppedPythonFile(*args):
    import maya.cmds as cmds
    import maya.mel as mel
    import os
    import shutil
    
    src_path = os.path.abspath(__file__)
    filename = os.path.basename(src_path)
    module_name = os.path.splitext(filename)[0]
    
    scripts_dir = cmds.internalVar(userScriptDir=True)
    dest_file = os.path.join(scripts_dir, filename)
    
    if os.path.normpath(src_path) != os.path.normpath(dest_file):
        shutil.copy(src_path, dest_file)
        
    top_shelf = mel.eval('$tmpVar=$gShelfTopLevel')
    current_shelf = cmds.tabLayout(top_shelf, query=True, selectTab=True)
    
    icon_path = get_icon_path()
    
    exec_command = (
        f"import {module_name}\n"
        f"import importlib\n"
        f"importlib.reload({module_name})\n"
        f"{module_name}.launch_tool()"
    )
    
    cmds.shelfButton(
        parent=current_shelf,
        command=exec_command,
        sourceType="Python",
        annotation="Launch Reference Importer",
        image=icon_path,
        imageOverlayLabel=""
    )
    
    cmds.confirmDialog(
        title="Installation Successful", 
        message=f"Tool installed to the '{current_shelf}' shelf.\n\nThe script was copied to your Maya scripts folder.",
        icon="information"
    )